//! Golden comparison of the zap log sink against controller-runtime's zap logger
//! (fixtures generated by `go run -mod=vendor ./hack/golden/zaplog crates/ctrlrt-cmd/tests/fixtures/zaplog`).

use std::io::Write;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

use chrono::{DateTime, FixedOffset};
use ctrlrt::log::Logger;
use ctrlrt_cmd::flag::{ErrorHandling, FlagSet};
use ctrlrt_cmd::zap::{ZapOptions, ZapSink, fixed_clock};
use k8s_openapi::api::core::v1::{ObjectReference, Pod};
use k8s_openapi::apimachinery::pkg::apis::meta::v1::ObjectMeta;
use serde_json::{Value, json};

#[derive(Default)]
struct Buf(Vec<u8>);
impl Write for Buf {
    fn write(&mut self, b: &[u8]) -> std::io::Result<usize> {
        self.0.extend_from_slice(b);
        Ok(b.len())
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/zaplog")
}

/// Mirror of the Go program's `convert`: produce the Value the Rust port logs for the Go value.
fn convert(v: &Value) -> Value {
    match v {
        Value::Object(m) => {
            if let Some(r) = m.get("$objref") {
                let r: ObjectReference = serde_json::from_value(r.clone()).unwrap();
                return serde_json::to_value(r).unwrap();
            }
            if let Some(r) = m.get("$kref") {
                let ns = r[0].as_str().unwrap();
                let name = r[1].as_str().unwrap();
                return if ns.is_empty() { json!({ "name": name }) } else { json!({ "name": name, "namespace": ns }) };
            }
            if let Some(r) = m.get("$err") {
                return r.clone();
            }
            if let Some(r) = m.get("$pod") {
                let pod = Pod {
                    metadata: ObjectMeta {
                        namespace: Some(r[0].as_str().unwrap().into()),
                        name: Some(r[1].as_str().unwrap().into()),
                        ..Default::default()
                    },
                    ..Default::default()
                };
                return serde_json::to_value(pod).unwrap();
            }
            Value::Object(m.iter().map(|(k, v)| (k.clone(), convert(v))).collect())
        }
        Value::Array(a) => Value::Array(a.iter().map(convert).collect()),
        other => other.clone(),
    }
}

fn kvs(v: Option<&Value>) -> Vec<(String, Value)> {
    let Some(Value::Array(a)) = v else { return vec![] };
    a.chunks(2)
        .map(|c| (c[0].as_str().unwrap().to_string(), convert(&c[1])))
        .collect()
}

fn run(sc: &Value, stacks: bool) -> String {
    let mut opts = ZapOptions {
        development: sc["development"].as_bool().unwrap(),
        ..Default::default()
    };
    let mut fs = FlagSet::new("zaplog", ErrorHandling::ContinueOnError);
    opts.bind_flags(&mut fs);
    let flags: Vec<String> = sc["flags"]
        .as_array()
        .map(|a| a.iter().map(|s| s.as_str().unwrap().to_string()).collect())
        .unwrap_or_default();
    fs.parse(flags).unwrap();
    opts.apply_flags(&fs);
    let buf = Arc::new(Mutex::new(Buf::default()));
    opts.dest = Some(buf.clone());
    let t = DateTime::parse_from_rfc3339(sc["time"].as_str().unwrap()).unwrap();
    let off = FixedOffset::east_opt(sc["tzOffset"].as_i64().unwrap_or(0) as i32).unwrap();
    opts.clock = Some(fixed_clock(t.with_timezone(&off)));
    let mut sink = ZapSink::new(&opts);
    if !stacks {
        sink = sink.without_stacktraces();
    }
    let root = Logger::with_sink(Arc::new(sink));
    for op in sc["ops"].as_array().unwrap() {
        let mut l = root.clone();
        if let Some(names) = op.get("names").and_then(Value::as_array) {
            for n in names {
                l = l.with_name(n.as_str().unwrap());
            }
        }
        let values = kvs(op.get("values"));
        if !values.is_empty() {
            l = l.with_values(values);
        }
        let repeat = op.get("repeat").and_then(Value::as_u64).unwrap_or(1).max(1);
        let msg = op["msg"].as_str().unwrap();
        for _ in 0..repeat {
            match op["kind"].as_str().unwrap() {
                "info" => l
                    .v(op.get("v").and_then(Value::as_i64).unwrap_or(0) as i32)
                    .info(msg, kvs(op.get("kvs"))),
                "error" => match op.get("err").and_then(Value::as_str) {
                    Some(e) => l.error(&e, msg, kvs(op.get("kvs"))),
                    None => l.error_nil(msg, kvs(op.get("kvs"))),
                },
                k => panic!("unknown kind {k}"),
            }
        }
    }
    let out = buf.lock().unwrap().0.clone();
    String::from_utf8(out).unwrap()
}

fn scenarios() -> Vec<Value> {
    let s = std::fs::read_to_string(dir().join("scenarios.json")).unwrap();
    serde_json::from_str::<Vec<Value>>(&s).unwrap()
}

#[test]
fn zap_output_matches_go_byte_for_byte() {
    let mut n = 0;
    for sc in scenarios() {
        let name = sc["name"].as_str().unwrap();
        if name.contains("stacktrace") {
            continue;
        }
        let want = std::fs::read_to_string(dir().join(sc["outputFile"].as_str().unwrap())).unwrap();
        let got = run(&sc, true);
        if got != want {
            for (i, (g, w)) in got.lines().zip(want.lines()).enumerate() {
                assert_eq!(g, w, "scenario {name}, line {i}");
            }
            assert_eq!(got, want, "scenario {name}");
        }
        n += 1;
    }
    assert!(n >= 20);
}

/// Stack traces are Go-specific; compare everything except the trace itself and check the
/// trace has zap's `function\n\tfile:line` shape.
#[test]
fn zap_stacktraces_have_go_shape() {
    for sc in scenarios() {
        let name = sc["name"].as_str().unwrap();
        if !name.contains("stacktrace") {
            continue;
        }
        let want = std::fs::read_to_string(dir().join(sc["outputFile"].as_str().unwrap())).unwrap();
        let got = run(&sc, true);
        if name.starts_with("prod") {
            let strip = |s: &str| -> Vec<Value> {
                s.lines()
                    .map(|l| {
                        let mut v: Value = serde_json::from_str(l).unwrap();
                        let had = v.as_object_mut().unwrap().remove("stacktrace").is_some();
                        json!([v.to_string(), had])
                    })
                    .collect()
            };
            assert_eq!(strip(&got), strip(&want), "{name}");
        } else {
            let first = |s: &str| -> Vec<String> {
                s.lines().filter(|l| l.starts_with("2024-")).map(str::to_string).collect()
            };
            assert_eq!(first(&got), first(&want), "{name}");
            // The error line is followed by a stack section (frames + "\tfile:line" lines).
            let after: Vec<&str> = got.lines().skip_while(|l| !l.contains("with stack")).skip(1).collect();
            for l in &after {
                assert!(!l.is_empty(), "{got}");
            }
        }
        // Without stack capture the output equals Go's minus the stack.
        let no_stack = run(&sc, false);
        assert!(!no_stack.contains("\n\t"), "{no_stack}");
    }
}

